tool_input.content:
import { chromium } from 'playwright'
import fs from 'node:fs'
import path from 'node:path'

const cssPath = 'D:/repository/苏州市房地产监测V3/dist/assets/detail-template-BX9m-ONp.css'
let css = fs.readFileSync(cssPath, 'utf8')

// 旧样式还原：把本次修复反向覆盖
const oldOverride = `
.value-area.auto-height{align-items:center !important}
.value-area.auto-height{height:auto;min-height:44px;overflow:hidden !important}
.value-area.auto-height .detail-value{align-items:center !important}
.detail-image{width:100px;height:100px !important;max-height:none !important}
.attachment-image{width:100px;height:100px !important;max-height:none !important}
`

const V = 'data-v-35da3bc0'
const fields = [
  '地块编号', '不动权证号', '土地用途',
  '土地面积', '出让价格', '出让日期',
  '宗地坐落', '四界-东界', '四界-西界',
  '四界-南界', '四界-北界',
]
const values = ['320505-2024-001', '苏(2024)不动产权第0012号', '城镇住宅用地',
  '12345.67 ㎡', '8888.00 万元', '2024-06-18',
  '苏州市高新区科技城峨眉山路8号', '东至规划道路', '西至空地',
  '南至河道', '北至现状厂房']

function imgSlot() {
  // 用 100x100 的 div 模拟图片（尺寸与 .attachment-image 一致）
  return `<div class="attachment-list"><div class="attachment-item">
    <div class="attachment-image" style="background:#b8d4e8"></div>
  </div></div>`
}

function cell(label, valueHtml, auto) {
  return `<div class="detail-row"><div class="detail-item">
    <div class="label-area ${auto ? 'auto-height' : ''}"><div class="detail-label"><div class="detail-label-main"><span>${label}</span></div></div></div>
    <div class="value-area ${auto ? 'auto-height' : ''}"><div class="detail-value text-left"><div class="detail-text-wrapper"><span class="detail-text">${valueHtml}</span></div></div></div>
  </div></div>`
}

// 三列：每行 3 个 item（含图片占整行 fullRow）
function buildBody(fullRowImg) {
  let rows = ''
  // 前 11 个文本字段，3 个一行
  for (let i = 0; i < fields.length; i += 3) {
    let r = '<div class="detail-row">'
    for (let j = i; j < i + 3 && j < fields.length; j++) {
      r += `<div class="detail-item" style="width:33.333%">
        <div class="label-area"><div class="detail-label"><div class="detail-label-main"><span>${fields[j]}</span></div></div></div>
        <div class="value-area"><div class="detail-value text-left"><div class="detail-text-wrapper"><span class="detail-text">${values[j]}</span></div></div></div>
      </div>`
    }
    r += '</div>'
    rows += r
  }
  if (fullRowImg) {
    // 图片独占整行（fullRow:true 效果）
    rows += `<div class="detail-row"><div class="detail-item" style="width:100%">
      <div class="label-area auto-height"><div class="detail-label"><div class="detail-label-main"><span>土地出让合同</span></div></div></div>
      <div class="value-area auto-height"><div class="detail-value text-left">${imgSlot()}</div></div>
    </div></div>`
  } else {
    // 旧：图片与两个文本混在第 4 行
    rows += `<div class="detail-row">
      <div class="detail-item" style="width:33.333%">
        <div class="label-area"><div class="detail-label"><div class="detail-label-main"><span>四界-南界</span></div></div></div>
        <div class="value-area"><div class="detail-value text-left"><div class="detail-text-wrapper"><span class="detail-text">南至河道</span></div></div></div>
      </div>
      <div class="detail-item" style="width:33.333%">
        <div class="label-area"><div class="detail-label"><div class="detail-label-main"><span>四界-北界</span></div></div></div>
        <div class="value-area"><div class="detail-value text-left"><div class="detail-text-wrapper"><span class="detail-text">北至现状厂房</span></div></div></div>
      </div>
      <div class="detail-item" style="width:33.333%">
        <div class="label-area auto-height"><div class="detail-label"><div class="detail-label-main"><span>土地出让合同</span></div></div></div>
        <div class="value-area auto-height"><div class="detail-value text-left">${imgSlot()}</div></div>
      </div>
    </div>`
  }
  return rows
}

function page(body, oldCss) {
  const base = css.replaceAll(`[${V}]`, '')
  return `<!doctype html><html><head><meta charset="utf-8"><style>
  body{margin:0;font-family:"Microsoft YaHei",sans-serif;background:#fff}
  .mock-dialog{width:1000px;margin:20px auto;border:1px solid #ddd;padding:0 20px}
  .detail-template,.detail-content{width:100%}
  ${base}
  ${oldCss ? oldOverride : ''}
  </style></head><body><div class="mock-dialog"><div class="detail-content">${body}</div></div></body></html>`
}

const browser = await chromium.launch()
const pg = await browser.newPage({ viewport: { width: 1100, height: 1600 } })

const scenarios = [
  { name: 'old_3col_mixed', body: buildBody(false), oldCss: true, desc: '修复前：图片与文本混排+值居中+固定图高' },
  { name: 'new_3col_fullrow', body: buildBody(true), oldCss: false, desc: '修复后：图片整行+autoHeight顶部对齐+max-height' },
]

const outDir = 'D:/repository/worktrees/szfc-v3-wt-bug6012-detail-gap/.tmp-bug6012'
fs.mkdirSync(outDir, { recursive: true })

for (const s of scenarios) {
  const html = page(s.body, s.oldCss)
  fs.writeFileSync(path.join(outDir, s.name + '.html'), html)
  await pg.setContent(html)
  await pg.waitForTimeout(200)
  // 测量每个 .detail-row 的高度与相邻间距
  const metrics = await pg.evaluate(() => {
    const rows = [...document.querySelectorAll('.detail-row')]
    const out = []
    for (let i = 0; i < rows.length; i++) {
      const r = rows[i].getBoundingClientRect()
      out.push({ i, top: Math.round(r.top), height: Math.round(r.height) })
    }
    return out
  })
  console.log(`\n=== ${s.name} (${s.desc}) ===`)
  let prevBottom = null
  metrics.forEach((m) => {
    const gap = prevBottom == null ? '-' : (m.top - prevBottom)
    console.log(`  row${m.i}: top=${m.top} h=${m.height} gapFromPrev=${gap}`)
    prevBottom = m.top + m.height
  })
  await pg.screenshot({ path: path.join(outDir, s.name + '.png'), fullPage: true })
}

await browser.close()
console.log('\nScreenshots & HTML written to', outDir)

