const metrics = await pg.evaluate(() => {
  const rows = [...document.querySelectorAll('.detail-row')]
  const out = []
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i].getBoundingClientRect()
    // 统计该行内每个 .detail-value 的可视内容高度（通过内部 wrapper/img）
    const items = [...rows[i].querySelectorAll('.detail-item')]
    const itemInfo = items.map((it) => {
      const rr = it.getBoundingClientRect()
      const lbl = it.querySelector('.detail-label')
      const val = it.querySelector('.value-area')
      const inner = it.querySelector('.detail-text-wrapper')
      const img = it.querySelector('.attachment-image')
      return {
        itemH: Math.round(rr.height),
        labelH: lbl ? Math.round(lbl.getBoundingClientRect().height) : 0,
        valueH: val ? Math.round(val.getBoundingClientRect().height) : 0,
        contentH: img ? Math.round(img.getBoundingClientRect().height) : (inner ? Math.round(inner.getBoundingClientRect().height) : 0),
      }
    })
    out.push({ i, top: Math.round(r.top), height: Math.round(r.height), items: itemInfo })
  }
  return out
})
console.log(`\n=== ${s.name} (${s.desc}) ===`)
